"""Inspect the local workspace: find SQLite databases and report their schema.

Task-local helper used to decide how the requested login/registration
script should target the SQLite database in this folder.
"""

import os
import sqlite3

SUFFIXES = (".db", ".sqlite", ".sqlite3", ".db3", ".sql3")


def candidate_dirs():
    dirs = [os.getcwd()]
    script_dir = os.path.dirname(os.path.abspath(__file__))
    if script_dir not in dirs:
        dirs.append(script_dir)
    return dirs


def find_databases():
    found = []
    for d in candidate_dirs():
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for name in names:
            low = name.lower()
            if any(low.endswith(s) for s in SUFFIXES) and not name.startswith("."):
                full = os.path.normpath(os.path.join(d, name))
                if full not in found:
                    found.append(full)
    return found


def inspect(path):
    print("\n" + "=" * 60)
    print("DATABASE:", path)
    print("=" * 60)
    try:
        uri = "file:" + path.replace("?", "%3f") + "?mode=ro"
        conn = sqlite3.connect(uri, uri=True)
    except sqlite3.Error as exc:
        print("Could not open:", exc)
        return
    with conn:
        cur = conn.cursor()
        try:
            rows = cur.execute(
                "SELECT type, name, sql FROM sqlite_master "
                "WHERE type IN ('table','index','view') ORDER BY type, name"
            ).fetchall()
        except sqlite3.Error as exc:
            print("sqlite_master read failed:", exc)
            return
        if not rows:
            print("(database appears empty - no schema objects)")
            return
        for kind, name, ddl in rows:
            print(f"-- {kind}: {name}")
            if ddl:
                print(ddl)
            if kind == "table" and not name.startswith("sqlite_"):
                quoted = name.replace('"', '""')
                try:
                    count = cur.execute(
                        'SELECT COUNT(*) FROM "%s"' % quoted
                    ).fetchone()[0]
                    print(f"   rows: {count}")
                except sqlite3.Error:
                    pass


def main():
    print("Working directory:", os.getcwd())
    print("Files in this folder:")
    try:
        for name in sorted(os.listdir(os.getcwd())):
            print(" -", name)
    except OSError as exc:
        print("   (cannot list:", exc, ")")

    dbs = find_databases()
    print("\nSQLite database files found:", dbs or "(none)")
    for db in dbs:
        inspect(db)


if __name__ == "__main__":
    main()

